static cl_mem
new_image(const char *how, cl_mem_flags flags, const cl_image_format *f, const cl_image_desc *d,
          void *host_ptr, cl_int *errcode_ret)
{
    size_t row = d->image_row_pitch ? d->image_row_pitch
                                    : d->image_width * channels(f->image_channel_order) *
                                      channel_bytes(f->image_channel_data_type);
    size_t h = d->image_height ? d->image_height : 1;
    size_t depth = d->image_depth ? d->image_depth : (d->image_array_size ? d->image_array_size : 1);
    struct obj *o;
    cl_mem m;

    if (d->buffer) {        /* an image over a buffer (cl_khr_image2d_from_buffer) */
        o = new_obj(K_MEM);
        o->parent = &d->buffer->o;
        o->host = d->buffer->o.host;
        o->size = row * h;
        m = (cl_mem)o;
    } else {
        m = new_mem(d->image_type, flags, row * h * depth, host_ptr);
        o = &m->o;
    }
    o->mem_type = d->image_type;
    o->format = *f;
    o->desc = *d;
    o->desc.image_row_pitch = row;
    static int n;
    if (n++ < 300)
        LOG("%s mem%d type=0x%x %zux%zux%zu %s/0x%x pitch=%zu flags=0x%llx%s", how, o->id,
            d->image_type, d->image_width, d->image_height, d->image_depth,
            order_name(f->image_channel_order), f->image_channel_data_type, row,
            (unsigned long long)flags, d->buffer ? " from-buffer" : "");
    if (errcode_ret)
        *errcode_ret = CL_SUCCESS;
    return m;
}

