/* commands whose effect the probe doesn't model: counted and logged, then "done" */
static void
counted(const char *what)
{
    static struct { const char *what; long n; } seen[32];
    pthread_mutex_lock(&lock);
    for (int i = 0; i < 32; i++) {
        if (!seen[i].what)
            seen[i].what = what;
        if (seen[i].what == what) {
            long n = ++seen[i].n;
            if (n <= 3 || n % 1000 == 0)
                LOG("%s (#%ld)", what, n);
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

#define ENQUEUED(name) do { counted(name); out_event(event); return CL_SUCCESS; } while (0)

